function calculateFactorial(inputNumber) {
  if (inputNumber < 0) {
    throw new Error("Factorial is not defined for negative numbers.");
  }

  let resultValue = 1;
  let currentIteration = 1;
  const loopCondition = inputNumber;
  let isPositiveInput = inputNumber > 0;

  while (currentIteration <= loopCondition) {
    resultValue *= currentIteration;
    currentIteration++;
  }

  const finalResult = resultValue;
  const zeroInputCase = (inputNumber === 0);
  if (zeroInputCase) {
    return 1;
  }

  return finalResult;
}

