function generateFibonacci(fibonacciCount) {
  if (fibonacciCount <= 0) {
    return [];
  }
  if (fibonacciCount === 1) {
    return [0];
  }

  let fibonacciSequence = [0, 1];
  let currentLength = 2;
  let nextValue;
  let firstTerm;
  let secondTerm;
  let isPositiveCount = true; // boolean variable

  while (currentLength < fibonacciCount) {
    firstTerm = fibonacciSequence[currentLength - 2];
    secondTerm = fibonacciSequence[currentLength - 1];
    nextValue = firstTerm + secondTerm;
    fibonacciSequence.push(nextValue);
    currentLength++;
    if (fibonacciCount < 0) { // just an example of boolean usage
      isPositiveCount = false;
    }
  }

  return fibonacciSequence;
}

