const isPrime = (candidateNumber) => {
  if (candidateNumber <= 1) {
    return false;
  }
  let loopStart = 2;
  const loopEnd = Math.sqrt(candidateNumber);
  let isNumberPrime = true;

  while (loopStart <= loopEnd) {
    const remainderValue = candidateNumber % loopStart;
    if (remainderValue === 0) {
      isNumberPrime = false;
      break;
    }
    loopStart++;
  }
  const finalResult = isNumberPrime;
  return finalResult;
};

