function calculateDistance(pointOne, pointTwo) {
  const xCoordOne = pointOne.x;
  const yCoordOne = pointOne.y;
  const xCoordTwo = pointTwo.x;
  const yCoordTwo = pointTwo.y;

  const deltaX = xCoordTwo - xCoordOne;
  const deltaY = yCoordTwo - yCoordOne;

  const squaredDeltaX = deltaX * deltaX;
  const squaredDeltaY = deltaY * deltaY;

  const sumOfSquares = squaredDeltaX + squaredDeltaY;
  const finalDistance = Math.sqrt(sumOfSquares);

  let isPositive = finalDistance >= 0;

  return finalDistance;
}

