  const resultSortedArray = [];
  let numberOfElements = inputArray.length;

  if (!isInputValid || numberOfElements === 0) {
    return resultSortedArray;
  }

  const temporaryCopy = [...inputArray];
  let sortOperationCompleted = false;

  while (!sortOperationCompleted) {
    let swapsMadeThisPass = false;
    for (let i = 0; i < numberOfElements - 1; i++) {
      const currentNumber = temporaryCopy[i];
      const nextNumber = temporaryCopy[i + 1];
      if (currentNumber > nextNumber) {
