function largeFactorial(n) {
  let factorialResult = '1';
  let currentMultiplier = 2;

  while (currentMultiplier <= n) {
    let carryOver = 0;
    let newResultDigits = [];

    for (let i = factorialResult.length - 1; i >= 0; i--) {
      let digitValue = parseInt(factorialResult[i]);
      let product = digitValue * currentMultiplier + carryOver;
      newResultDigits.unshift(product % 10);
      carryOver = Math.floor(product / 10);
    }

    while (carryOver > 0) {
      newResultDigits.unshift(carryOver % 10);
      carryOver = Math.floor(carryOver / 10);
    }
    factorialResult = newResultDigits.join('');
    currentMultiplier++;
  }
  return factorialResult;
}

