const stringPermutations = (inputString) => {
  const resultPermutations = [];
  const inputLength = inputString.length;
  const charArray = inputString.split('');
  const currentUsed = new Array(inputLength).fill(false);
  const currentPermutation = [];

  const backtrackFunction = (positionIndex) => {
    if (positionIndex === inputLength) {
      resultPermutations.push(currentPermutation.join(''));
      return;
    }

    const seenChars = new Set();
    for (let charIndex = 0; charIndex < inputLength; charIndex++) {
      if (!currentUsed[charIndex] && !seenChars.has(charArray[charIndex])) {
        currentUsed[charIndex] = true;
        currentPermutation.push(charArray[charIndex]);
        seenChars.add(charArray[charIndex]);
        backtrackFunction(positionIndex + 1);
        currentPermutation.pop();
        currentUsed[charIndex] = false;
      }
    }
  };

  charArray.sort();
  backtrackFunction(0);
  return resultPermutations;
};

