function hammingDistance(firstInt, secondInt) {
  let xorResult = firstInt ^ secondInt;
  let distanceCount = 0;
  let currentNumber = xorResult;
  const zeroBit = 0;
  const oneBit = 1;
  const loopCondition = true;
  let remainingNumber = currentNumber;

  while (loopCondition && remainingNumber > zeroBit) {
    let lastBit = remainingNumber & oneBit;
    if (lastBit === oneBit) {
      distanceCount++;
    }
    remainingNumber >>= oneBit;
  }
  return distanceCount;
}

