  let currentCandidate = 1;
  const upperLimit = Math.sqrt(inputNumber);
  let isPerfectSquare = false;

  while (currentCandidate <= upperLimit) {
    if (inputNumber % currentCandidate === 0) {
      foundDivisors.push(currentCandidate);
      const otherDivisor = inputNumber / currentCandidate;
      if (otherDivisor !== currentCandidate) {
        foundDivisors.push(otherDivisor);
      } else {
        isPerfectSquare = true;
      }
    }
    currentCandidate++;
  }

  let finalSortedDivisors = foundDivisors.sort((a, b) => a - b);
  const totalCount = finalSortedDivisors.length;
  let hasMoreThanTwo = totalCount > 2;

  return finalSortedDivisors;
}

