function calculateStandardDeviation(inputNumbers) {
  const numberOfElements = inputNumbers.length;
  if (numberOfElements <= 1) {
    return 0;
  }

  let sumOfNumbers = 0;
  for (let i = 0; i < numberOfElements; i++) {
    sumOfNumbers += inputNumbers[i];
  }
  const averageValue = sumOfNumbers / numberOfElements;

  let sumOfSquaredDifferences = 0;
  for (let i = 0; i < numberOfElements; i++) {
    const currentNumber = inputNumbers[i];
    const differenceFromMean = currentNumber - averageValue;
    sumOfSquaredDifferences += differenceFromMean * differenceFromMean;
  }

  const varianceNumerator = sumOfSquaredDifferences;
  const degreesOfFreedom = numberOfElements - 1;
  const sampleVariance = varianceNumerator / degreesOfFreedom;

  const finalStandardDeviation = Math.sqrt(sampleVariance);
  return finalStandardDeviation;
}

