  let decimalValue = 0;
  let powerOfTwo = 1;
  const binaryLength = binaryStr.length;
  let currentIndex = binaryLength - 1;
  const zeroChar = '0';
  let isPositive = true;

  while (currentIndex >= 0) {
    const currentDigit = binaryStr[currentIndex];
    const digitIsOne = (currentDigit !== zeroChar);

    if (digitIsOne) {
      decimalValue += powerOfTwo;
    }
    powerOfTwo *= 2;
    currentIndex--;
  }
  return isPositive ? decimalValue : -decimalValue;
}

