  let nStartIdx = 0;
  let nMaxLength = 1;
  const nStringLength = strS.length;

  for (let nI = 0; nI < nStringLength; nI++) {
    let nLeftPointer = nI - 1;
    let nRightPointer = nI + 1;
    let nCurrentLength = 1;

    while (nLeftPointer >= 0 && strS[nLeftPointer] === strS[nI]) {
      nLeftPointer--;
      nCurrentLength++;
    }

    while (nRightPointer < nStringLength && strS[nRightPointer] === strS[nI]) {
      nRightPointer++;
      nCurrentLength++;
    }

    while (nLeftPointer >= 0 && nRightPointer < nStringLength && strS[nLeftPointer] === strS[nRightPointer]) {
      nLeftPointer--;
      nRightPointer++;
      nCurrentLength += 2;
    }

    if (nCurrentLength > nMaxLength) {
      nMaxLength = nCurrentLength;
      nStartIdx = nLeftPointer + 1;
    }
  }

  const strResultString = strS.substring(nStartIdx, nStartIdx + nMaxLength);
