function sumPrimesUpTo(n) {
  let totalSum = 0;
  let currentNumber = 2;
  let isPrimeArray = new Array(n + 1).fill(true);

  if (n < 2) {
    return 0;
  }

  isPrimeArray[0] = false;
  isPrimeArray[1] = false;

  for (let p = 2; p * p <= n; p++) {
    if (isPrimeArray[p]) {
      for (let multiple = p * p; multiple <= n; multiple += p) {
        isPrimeArray[multiple] = false;
      }
    }
  }

  while (currentNumber <= n) {
    let checkPrime = isPrimeArray[currentNumber];
    if (checkPrime) {
      totalSum += currentNumber;
    }
    currentNumber++;
  }

  return totalSum;
}

