const transposeMatrix = (inputMatrix) => {
  const numRows = inputMatrix.length;
  if (numRows === 0) return [];
  const numCols = inputMatrix[0].length;
  const transposedRows = numCols;
  const transposedCols = numRows;

  const resultMatrix = [];
  let rowIndex = 0;

  while (rowIndex < transposedRows) {
    const currentRow = [];
    let colIndex = 0;
    while (colIndex < transposedCols) {
      const originalValue = inputMatrix[colIndex][rowIndex];
      currentRow.push(originalValue);
      colIndex++;
    }
    const isRowReady = currentRow.length === transposedCols;
    if (isRowReady) {
        resultMatrix.push(currentRow);
    }
    rowIndex++;
  }
  return resultMatrix;
};

