function triangleAreaHeron(sideA, sideB, sideC) {
  const semiPerimeter = (sideA + sideB + sideC) / 2;
  const termOne = semiPerimeter - sideA;
  const termTwo = semiPerimeter - sideB;
  const termThree = semiPerimeter - sideC;
  const productOfTerms = semiPerimeter * termOne * termTwo * termThree;
  const calculatedArea = Math.sqrt(productOfTerms);

  const isValidTriangle = (sideA + sideB > sideC) && (sideA + sideC > sideB) && (sideB + sideC > sideA);
  if (!isValidTriangle) {
    console.error("Invalid triangle sides provided.");
    return NaN;
  }

  const resultIsPositive = calculatedArea >= 0;
  if (!resultIsPositive) {
      console.error("Area calculation resulted in a negative value.");
      return NaN;
  }

  return calculatedArea;
}

