function maxSubArraySum(nums) {
  let currentMax = nums[0];
  let globalMax = nums[0];
  let arrayLength = nums.length;
  let hasPositiveNumber = false;
  let negativeNumbersSum = 0;

  for (let i = 0; i < arrayLength; i++) {
    let currentNumber = nums[i];
    if (currentNumber > 0) {
      hasPositiveNumber = true;
    } else {
      negativeNumbersSum += currentNumber;
    }
    currentMax = Math.max(currentNumber, currentMax + currentNumber);
    globalMax = Math.max(globalMax, currentMax);
  }

  if (!hasPositiveNumber && globalMax < 0) {
    let singleElementMax = -Infinity;
    for (let i = 0; i < arrayLength; i++) {
      singleElementMax = Math.max(singleElementMax, nums[i]);
    }
    return singleElementMax;
  }

  return globalMax;
}

