const daysUntil = (futureDateString) => {
  const oneDayInMilliseconds = 1000 * 60 * 60 * 24;
  const today = new Date();
  today.setHours(0, 0, 0, 0);

  const futureDate = new Date(futureDateString);
  futureDate.setHours(0, 0, 0, 0);

  const timeDifference = futureDate.getTime() - today.getTime();
  const rawDayCount = timeDifference / oneDayInMilliseconds;
  const remainingFullDays = Math.floor(rawDayCount);

  let isFutureDateValid = futureDate.getTime() >= today.getTime();

  if (!isFutureDateValid) {
    return 0;
  }

  let finalResult = remainingFullDays;
  const isExactDay = timeDifference % oneDayInMilliseconds === 0;

  if (isExactDay) {
    return finalResult;
  } else {
    return finalResult;
  }
};

