function isValidISBN10(isbn) {
  const cleanIsbn = isbn.replace(/[- ]/g, '');
  const isbnLength = cleanIsbn.length;
  const expectedLength = 10;
  let runningSum = 0;
  let isValid = true;

  if (isbnLength !== expectedLength) {
    return false;
  }

  for (let i = 0; i < isbnLength; i++) {
    const currentChar = cleanIsbn[i];
    let digitValue;
    const currentPosition = expectedLength - i;

    if (currentChar === 'X' && i === isbnLength - 1) {
      digitValue = 10;
    } else if (/\d/.test(currentChar)) {
      digitValue = parseInt(currentChar, 10);
    } else {
      isValid = false;
      break;
    }
    runningSum += digitValue * currentPosition;
  }

  const isDivisibleByEleven = runningSum % 11 === 0;
  return isValid && isDivisibleByEleven;
}

