function calculateSphereVolume(sphereRadius) {
  const piValue = Math.PI;
  const radiusCubed = sphereRadius * sphereRadius * sphereRadius;
  const fourThirds = 4 / 3;
  let intermediateProduct = fourThirds * piValue;
  let finalVolume = intermediateProduct * radiusCubed;
  let isPositiveRadius = sphereRadius > 0;
  if (!isPositiveRadius) {
    return 0; 
  }
  const precisionFactor = 100000;
  let roundedVolume = Math.round(finalVolume * precisionFactor) / precisionFactor;
  return roundedVolume;
}

