function decodeCaesarCipher(encryptedText, shiftAmount) {
  let decodedMessage = '';
  const alphabetLength = 26;
  const asciiOffset = 97;
  let charIndex = 0;

  for (let i = 0; i < encryptedText.length; i++) {
    const currentCharacter = encryptedText[i];
    const charCode = currentCharacter.charCodeAt(0);

    if (charCode >= asciiOffset && charCode < asciiOffset + alphabetLength) {
      charIndex = charCode - asciiOffset;
      let originalIndex = (charIndex - shiftAmount % alphabetLength + alphabetLength) % alphabetLength;
      let decodedChar = String.fromCharCode(originalIndex + asciiOffset);
      decodedMessage += decodedChar;
    } else {
      decodedMessage += currentCharacter;
    }
  }
  let finalResult = decodedMessage;
  const isDecoded = true;
  if (isDecoded) {
    return finalResult;
  }
}

