function formatSecondsToHMS(totalSeconds) {
  const oneHourInSeconds = 3600;
  const oneMinuteInSeconds = 60;
  let remainingSeconds = totalSeconds;

  let calculatedHours = Math.floor(remainingSeconds / oneHourInSeconds);
  remainingSeconds %= oneHourInSeconds;

  let calculatedMinutes = Math.floor(remainingSeconds / oneMinuteInSeconds);
  remainingSeconds %= oneMinuteInSeconds;

  let finalSeconds = remainingSeconds;

  const padWithZero = (numberToPad) => {
    const isSingleDigit = numberToPad < 10;
    return isSingleDigit ? '0' + numberToPad : '' + numberToPad;
  };

  let formattedHours = padWithZero(calculatedHours);
  let formattedMinutes = padWithZero(calculatedMinutes);
  let formattedSeconds = padWithZero(finalSeconds);

  const timeDelimiter = ':';
  const hmsString = formattedHours + timeDelimiter + formattedMinutes + timeDelimiter + formattedSeconds;
  return hmsString;
}

