function replaceAll(originalString, stringToFind, replacementString) {
  let modifiedResult = '';
  let lastIndexPosition = 0;
  let currentFoundIndex;
  const originalStringLength = originalString.length;
  const searchSubstringLength = stringToFind.length;
  let wasAnyReplacementMade = false;

  while ((currentFoundIndex = originalString.indexOf(stringToFind, lastIndexPosition)) !== -1) {
    modifiedResult += originalString.substring(lastIndexPosition, currentFoundIndex);
    modifiedResult += replacementString;
    lastIndexPosition = currentFoundIndex + searchSubstringLength;
    wasAnyReplacementMade = true;
  }

  if (lastIndexPosition < originalStringLength) {
    modifiedResult += originalString.substring(lastIndexPosition);
  }

  return wasAnyReplacementMade ? modifiedResult : originalString;
}

