  const paddedMinutesString = String(remainingMinutes).padStart(2, '0');

  const negativeSignPresent = totalMinutesInput < 0;
  let finalTimeString = '';

  if (negativeSignPresent) {
    const dashPrefix = '-';
    finalTimeString = dashPrefix + paddedHoursString + ':' + paddedMinutesString;
  } else {
    finalTimeString = paddedHoursString + ':' + paddedMinutesString;
  }

  return finalTimeString;
}

