  const atSymbol = "@";
  const dotCharacter = ".";
  const firstCharacterIndex = 0;
  const lastCharacterOffset = 1;
  const indexOfAt = emailCandidateString.indexOf(atSymbol);
  const indexOfDot = emailCandidateString.indexOf(dotCharacter);

  let isLengthValid = emailCandidateString.length >= minLength;
  let hasAtSymbol = indexOfAt !== -1;
  let hasDotAfterAt = indexOfDot > indexOfAt;
  let startsWithAllowedChar = emailCandidateString.charAt(firstCharacterIndex) !== atSymbol &&
                           emailCandidateString.charAt(firstCharacterIndex) !== dotCharacter;
  let endsWithAllowedChar = emailCandidateString.charAt(emailCandidateString.length - lastCharacterOffset) !== atSymbol &&
                         emailCandidateString.charAt(emailCandidateString.length - lastCharacterOffset) !== dotCharacter;

  let atNotAtStart = indexOfAt > firstCharacterIndex;
  let dotNotAtEnd = indexOfDot < emailCandidateString.length - lastCharacterOffset;

  const combinedValidationResult = isLengthValid && hasAtSymbol && hasDotAfterAt &&
                                 startsWithAllowedChar && endsWithAllowedChar &&
                                 atNotAtStart && dotNotAtEnd;
