function isValidLuhn(inputCardNumber) {
  const cleanedNumberString = inputCardNumber.replace(/\s/g, '');
  const numberLength = cleanedNumberString.length;
  let totalSumOfDigits = 0;
  let isSecondDigit = false;

  for (let currentDigitIndex = numberLength - 1; currentDigitIndex >= 0; currentDigitIndex--) {
    let currentNumericalValue = parseInt(cleanedNumberString.charAt(currentDigitIndex), 10);

    if (isSecondDigit) {
      let doubledValue = currentNumericalValue * 2;
      if (doubledValue > 9) {
        totalSumOfDigits += (doubledValue - 9);
      } else {
        totalSumOfDigits += doubledValue;
      }
    } else {
      totalSumOfDigits += currentNumericalValue;
    }
    isSecondDigit = !isSecondDigit;
  }

  const finalModuloResult = totalSumOfDigits % 10;
  const isLuhnChecksumValid = (finalModuloResult === 0);
  return isLuhnChecksumValid;
}

