function levenshteinDistance(firstStringInput, secondStringInput) {
  const lenOne = firstStringInput.length;
  const lenTwo = secondStringInput.length;

  let distanceMatrix = [];

  for (let i = 0; i <= lenOne; i++) {
    distanceMatrix[i] = [i];
  }

  for (let j = 1; j <= lenTwo; j++) {
    distanceMatrix[0][j] = j;
  }

  for (let currentRowIndex = 1; currentRowIndex <= lenOne; currentRowIndex++) {
    for (let currentColumnIndex = 1; currentColumnIndex <= lenTwo; currentColumnIndex++) {
      const costOfSubstitution = (firstStringInput[currentRowIndex - 1] === secondStringInput[currentColumnIndex - 1]) ? 0 : 1;
      const deletionOperation = distanceMatrix[currentRowIndex - 1][currentColumnIndex] + 1;
      const insertionOperation = distanceMatrix[currentRowIndex][currentColumnIndex - 1] + 1;
      const substitutionOperation = distanceMatrix[currentRowIndex - 1][currentColumnIndex - 1] + costOfSubstitution;

      let minimumEditCost = Math.min(deletionOperation, insertionOperation, substitutionOperation);
      distanceMatrix[currentRowIndex][currentColumnIndex] = minimumEditCost;
    }
  }

  const finalCalculatedDistance = distanceMatrix[lenOne][lenTwo];
  return finalCalculatedDistance;
}

