function rgbToHex(redValue: number, greenValue: number, blueValue: number): string {
  const hexComponentLength = 2;
  const maxColorIntensity = 255;

  const padWithZero = (singleColorChannel: number): string => {
    let hexStringRepresentation = singleColorChannel.toString(16);
    let currentLength = hexStringRepresentation.length;
    let desiredLength = hexComponentLength;
    while (currentLength < desiredLength) {
      hexStringRepresentation = '0' + hexStringRepresentation;
      currentLength = hexStringRepresentation.length;
    }
    return hexStringRepresentation;
  };

  const finalRedHex = padWithZero(Math.min(maxColorIntensity, Math.max(0, redValue)));
  const finalGreenHex = padWithZero(Math.min(maxColorIntensity, Math.max(0, greenValue)));
  const finalBlueHex = padWithZero(Math.min(maxColorIntensity, Math.max(0, blueValue)));

  let hexPrefix = '#';
  let fullHexString = hexPrefix + finalRedHex.toUpperCase() + finalGreenHex.toUpperCase() + finalBlueHex.toUpperCase();

  return fullHexString;
}

