function debounce(functionToExecute, executionDelayMilliseconds) {
  let timerIdForDebounce = null;
  let lastCallArguments = [];
  let lastCallThisContext = null;

  const debouncedFunctionWithArgs = function(...currentCallArgs) {
    const currentThisContext = this;
    lastCallArguments = currentCallArgs;
    lastCallThisContext = currentThisContext;

    const executeFunctionLater = () => {
      functionToExecute.apply(lastCallThisContext, lastCallArguments);
      timerIdForDebounce = null;
    };

    if (timerIdForDebounce) {
      clearTimeout(timerIdForDebounce);
    }
    timerIdForDebounce = setTimeout(executeFunctionLater, executionDelayMilliseconds);
  };
  return debouncedFunctionWithArgs;
}

