function generatePascalsRow(rowIndexNumber) {
  let currentRow = [];
  if (rowIndexNumber === 0) {
    currentRow.push(1);
    return currentRow;
  }

  let previousRow = generatePascalsRow(rowIndexNumber - 1);
  let previousRowLength = previousRow.length;
  currentRow.push(1);

  for (let currentElementIndex = 1; currentElementIndex < previousRowLength; currentElementIndex++) {
    let leftNeighborValue = previousRow[currentElementIndex - 1];
    let rightNeighborValue = previousRow[currentElementIndex];
    let sumOfNeighbors = leftNeighborValue + rightNeighborValue;
    currentRow.push(sumOfNeighbors);
  }

  currentRow.push(1);
  let finalResultArray = currentRow;
  return finalResultArray;
}

