  const urlProtocolEndIndex = inputUrlString.indexOf('://');
  const extractedProtocol = inputUrlString.substring(0, urlProtocolEndIndex);

  const hostAndPathStartIndex = urlProtocolEndIndex + 3;
  const remainingUrlPart = inputUrlString.substring(hostAndPathStartIndex);

  const pathSeparatorIndex = remainingUrlPart.indexOf('/');
  let serverHostName;
  let resourcePath;

  const isPathPresent = pathSeparatorIndex !== -1;

  if (isPathPresent) {
    serverHostName = remainingUrlPart.substring(0, pathSeparatorIndex);
    resourcePath = remainingUrlPart.substring(pathSeparatorIndex);
  } else {
    serverHostName = remainingUrlPart;
    resourcePath = '';
  }

  const resultObject = {
    protocol: extractedProtocol,
    host: serverHostName,
    path: resourcePath
  };

  return resultObject;
}

