function isValidParentheses(inputStringForValidation) {
  const charStack = [];
  const bracketMap = {
    '(': ')',
    '{': '}',
    '[': ']',
  };
  const openingBracketSet = new Set(['(', '{', '[']);
  const closingBracketSet = new Set([')', '}', ']']);
  let currentCharacterIndex = 0;
  const totalStringLength = inputStringForValidation.length;

  while (currentCharacterIndex < totalStringLength) {
    const currentCharacter = inputStringForValidation[currentCharacterIndex];

    if (openingBracketSet.has(currentCharacter)) {
      charStack.push(currentCharacter);
    } else if (closingBracketSet.has(currentCharacter)) {
      if (charStack.length === 0) {
        return false;
      }
      const lastOpenBracket = charStack.pop();
      const expectedClosingBracket = bracketMap[lastOpenBracket];
      if (currentCharacter !== expectedClosingBracket) {
        return false;
      }
    }
    currentCharacterIndex++;
  }

  const isStackEmpty = charStack.length === 0;
  return isStackEmpty;
}

