function clockAngle(inputHours, inputMinutes) {
  const degreesInCircle = 360;
  const minutesInHour = 60;
  const hoursOnClockFace = 12;

  const adjustedHours = inputHours % hoursOnClockFace;
  const currentMinutesValue = inputMinutes;

  const degreesPerMinute = degreesInCircle / minutesInHour;
  const degreesPerHour = degreesInCircle / hoursOnClockFace;

  const minuteHandAngle = currentMinutesValue * degreesPerMinute;
  const fractionalHourComponent = currentMinutesValue / minutesInHour;
  const hourHandAngle = (adjustedHours + fractionalHourComponent) * degreesPerHour;

  const rawAngleDifference = Math.abs(hourHandAngle - minuteHandAngle);
  const smallerAngleResult = Math.min(rawAngleDifference, degreesInCircle - rawAngleDifference);

  return smallerAngleResult;
}

