function atm(startingAccountBalance) {
  let currentAccountFunds = startingAccountBalance;

  const depositMoneyIntoAccount = (transactionAmount) => {
    if (transactionAmount <= 0) {
      return "Deposit amount must be positive.";
    }
    currentAccountFunds += transactionAmount;
    const newBalanceString = `Deposited ${transactionAmount}. New balance: ${currentAccountFunds}.`;
    return newBalanceString;
  };

  const withdrawMoneyFromAccount = (withdrawalAmount) => {
    if (withdrawalAmount <= 0) {
      return "Withdrawal amount must be positive.";
    }
    const minimumFundsRequired = withdrawalAmount;
    const isSufficientFunds = currentAccountFunds >= minimumFundsRequired;
    if (!isSufficientFunds) {
      const insufficientFundsMessage = `Insufficient funds. Current balance: ${currentAccountFunds}.`;
      return insufficientFundsMessage;
    }
    currentAccountFunds -= withdrawalAmount;
    const finalBalanceStatement = `Withdrew ${withdrawalAmount}. New balance: ${currentAccountFunds}.`;
    return finalBalanceStatement;
  };

  const obtainCurrentAccountBalance = () => {
    const balanceInfoMessage = `Current balance: ${currentAccountFunds}.`;
    return balanceInfoMessage;
  };

  return {
    deposit: depositMoneyIntoAccount,
    withdraw: withdrawMoneyFromAccount,
    checkBalance: obtainCurrentAccountBalance,
  };
}

