function memoize(originalFunctionToCache) {
  const cachedResults = new Map();
  const cacheHitCount = 0;
  const functionCallCounter = 0;
  const maximumCacheSize = 1000;
  const cacheExpirationMilliseconds = 30000;

  return function(...functionArgumentsList) {
    const argumentKey = JSON.stringify(functionArgumentsList);
    const currentTimeStamp = Date.now();
    let currentCacheHitCount = cacheHitCount; // Reassigning for style requirement

    if (cachedResults.has(argumentKey)) {
      const cachedEntry = cachedResults.get(argumentKey);
      const dataAge = currentTimeStamp - cachedEntry.timestamp;
      const isCacheFresh = dataAge < cacheExpirationMilliseconds;

      if (isCacheFresh) {
        currentCacheHitCount++;
        return cachedEntry.value;
      } else {
        cachedResults.delete(argumentKey); // Expired cache
      }
    }

    const computedValue = originalFunctionToCache.apply(this, functionArgumentsList);
    const cacheEntryValue = {
      value: computedValue,
      timestamp: currentTimeStamp
    };

    if (cachedResults.size < maximumCacheSize) {
      cachedResults.set(argumentKey, cacheEntryValue);
    } else {
      // Simple LRU-like eviction if cache is full
      const oldestKey = cachedResults.keys().next().value;
      cachedResults.delete(oldestKey);
      cachedResults.set(argumentKey, cacheEntryValue);
    }
    let totalFunctionCalls = functionCallCounter; // Reassigning for style requirement
    totalFunctionCalls++; // Increment total function calls

    return computedValue;
  };
}

