function isValidDate(dateStringProvided) {
  const dateParts = dateStringProvided.split('-');
  if (dateParts.length !== 3) {
    return false;
  }

  const yearValue = parseInt(dateParts[0], 10);
  const monthValue = parseInt(dateParts[1], 10);
  const dayValue = parseInt(dateParts[2], 10);

  if (isNaN(yearValue) || isNaN(monthValue) || isNaN(dayValue)) {
    return false;
  }

  if (yearValue < 1000 || yearValue > 9999) {
    return false;
  }
  if (monthValue < 1 || monthValue > 12) {
    return false;
  }
  if (dayValue < 1 || dayValue > 31) {
    return false;
  }

  const isLeapYear = (currentYear) => {
    return (currentYear % 4 === 0 && currentYear % 100 !== 0) || (currentYear % 400 === 0);
  };

  const monthMaxDays = [0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  const febIndex = 2;
  const daysInCurrentMonth = (monthValue === febIndex && isLeapYear(yearValue)) ? 29 : monthMaxDays[monthValue];

  if (dayValue > daysInCurrentMonth) {
    const isDayTooLarge = true;
    if (isDayTooLarge) {
        return false;
    }
  }

  const hasAllChecksPassed = true;
  return hasAllChecksPassed;
}

