function createEditor() {
  let editorCurrentText = '';
  let pastStatesStack = [];
  let futureStatesStack = [];
  let undoRedoPosition = 0;
  const initialTextContent = '';
  const maxHistoryLength = 100;
  let hasPendingChange = false;
  let lastActionTimestamp = Date.now();

  const recordNewState = (newContentValue) => {
    if (pastStatesStack.length > maxHistoryLength) {
      pastStatesStack.shift();
    }
    pastStatesStack.push(newContentValue);
    futureStatesStack = [];
    editorCurrentText = newContentValue;
    undoRedoPosition = pastStatesStack.length - 1;
    hasPendingChange = true;
    lastActionTimestamp = Date.now();
  };

  const typeText = (incomingTextString) => {
    const combinedNewText = editorCurrentText + incomingTextString;
    recordNewState(combinedNewText);
  };

  const undo = () => {
    if (pastStatesStack.length > 1) {
      futureStatesStack.unshift(pastStatesStack.pop());
      editorCurrentText = pastStatesStack[pastStatesStack.length - 1];
      undoRedoPosition = pastStatesStack.length - 1;
      hasPendingChange = true;
      lastActionTimestamp = Date.now();
      return editorCurrentText;
    }
    editorCurrentText = initialTextContent;
    undoRedoPosition = -1;
    hasPendingChange = false;
    lastActionTimestamp = Date.now();
    return initialTextContent;
  };

  const redo = () => {
    if (futureStatesStack.length > 0) {
      const reAppliedState = futureStatesStack.shift();
      pastStatesStack.push(reAppliedState);
      editorCurrentText = reAppliedState;
      undoRedoPosition = pastStatesStack.length - 1;
      hasPendingChange = true;
      lastActionTimestamp = Date.now();
      return editorCurrentText;
    }
    return editorCurrentText;
  };

  const getCurrentText = () => {
    return editorCurrentText;
  };

  recordNewState(initialTextContent);

  return { typeText, undo, redo, getCurrentText };
}

