function closestPair1D(allPoints) {
  const numberCount = allPoints.length;
  if (numberCount < 2) {
    return 0;
  }

  const sortedPoints = [...allPoints].sort((a, b) => a - b);
  let minDistanceSoFar = Infinity;
  let previousPointValue = sortedPoints[0];

  for (let i = 1; i < numberCount; i++) {
    const currentPointValue = sortedPoints[i];
    const currentDifference = currentPointValue - previousPointValue;
    if (currentDifference < minDistanceSoFar) {
      minDistanceSoFar = currentDifference;
    }
    previousPointValue = currentPointValue;
  }

  const finalClosestDistance = minDistanceSoFar;
  return finalClosestDistance;
}

