function calculateStdDev(inputNumberArray) {
  const numberOfElements = inputNumberArray.length;
  let sumOfNumbers = 0;
  for (let currentNumber of inputNumberArray) {
    sumOfNumbers += currentNumber;
  }

  const arithmeticMean = sumOfNumbers / numberOfElements;
  let sumOfSquaredDifferences = 0;

  for (let singleDataPoint of inputNumberArray) {
    const deviationFromMean = singleDataPoint - arithmeticMean;
    const squaredDeviation = deviationFromMean * deviationFromMean;
    sumOfSquaredDifferences += squaredDeviation;
  }

  const varianceNumerator = sumOfSquaredDifferences;
  const degreesOfFreedom = numberOfElements - 1;
  const sampleVariance = varianceNumerator / degreesOfFreedom;

  const finalStandardDeviation = Math.sqrt(sampleVariance);
  return finalStandardDeviation;
}

