const rotateMatrix = (inputMatrix) => {
  const matrixSize = inputMatrix.length;
  for (let layerIndex = 0; layerIndex < Math.floor(matrixSize / 2); layerIndex++) {
    const firstElementIndex = layerIndex;
    const lastElementIndex = matrixSize - 1 - layerIndex;
    for (let currentOffset = firstElementIndex; currentOffset < lastElementIndex; currentOffset++) {
      const topRowElement = inputMatrix[firstElementIndex][currentOffset];
      const rightColumnElement = inputMatrix[currentOffset][lastElementIndex];
      const bottomRowElement = inputMatrix[lastElementIndex][lastElementIndex - currentOffset + firstElementIndex];
      const leftColumnElement = inputMatrix[lastElementIndex - currentOffset + firstElementIndex][firstElementIndex];

      inputMatrix[firstElementIndex][currentOffset] = leftColumnElement;
      inputMatrix[currentOffset][lastElementIndex] = topRowElement;
      inputMatrix[lastElementIndex][lastElementIndex - currentOffset + firstElementIndex] = rightColumnElement;
      inputMatrix[lastElementIndex - currentOffset + firstElementIndex][firstElementIndex] = bottomRowElement;
    }
  }
};

