function isPerfectSquare(inputNumberToCheck) {
  if (inputNumberToCheck < 1) {
    return false;
  }
  if (inputNumberToCheck === 1) {
    return true;
  }

  let leftBoundary = 1;
  let rightBoundary = Math.floor(inputNumberToCheck / 2);
  let currentMiddleNumber;
  let calculatedSquareValue;

  while (leftBoundary <= rightBoundary) {
    currentMiddleNumber = Math.floor(leftBoundary + (rightBoundary - leftBoundary) / 2);
    calculatedSquareValue = currentMiddleNumber * currentMiddleNumber;

    if (calculatedSquareValue === inputNumberToCheck) {
      let finalResultStatus = true;
      return finalResultStatus;
    } else if (calculatedSquareValue < inputNumberToCheck) {
      leftBoundary = currentMiddleNumber + 1;
    } else {
      rightBoundary = currentMiddleNumber - 1;
    }
  }

  let isNotPerfect = false;
  return isNotPerfect;
}

